        desc = {
            ALCAZ = "Ein Gefängnis der Defias auf der Insel Alcaz, in dem einst Adlige für Lösegeld festgehalten wurden, heute von den Naga belagert.",
            BARROW = "In einem weitläufigen Netz aus Grabhügeln der Nachtelfen werden die gefährlichsten Gefangenen der Welt festgehalten, und die Verderbnis breitet sich aus.",
            BFD = "Ein überfluteter Tempel der Nachtelfen am Zoramstrand, heute in der Hand von Naga, Satyrn und dem Twilight-Hammer, die Aku'mai dienen.",
            BLACKMAW = "Eine große Stadt der Furbolgs im Norden von Azshara, die gegen ihre eigene Verderbnis kämpft. Ihre Tunnel reichen tief in Richtung Tiefengrabhügel.",
            BRD = "Die glühende Hauptstadt der Dunkeleisenzwerge unter dem Blackrock, beherrscht von Imperator Dagran Thaurissan.",
            DAL = "Die Barriere der Kirin Tor versagt, und die violette Stadt wird von entfesselten Verzauberungen, arkanen Konstrukten und austretender dämonischer Energie überrannt.",
            DM = "Unter den verlassenen Minen von Moonbrook baut die Bruderschaft der Defias unter Edwin van Cleef ein gewaltiges Kriegsschiff, um Stormwind anzugreifen.",
            DME = "Die überwucherten Gärten im Osten von Eldre'Thalas, in denen Alzzin der Wildformer die uralte Wucherborke verdirbt.",
            DMN = "Die Oger der Gordok haben die nördlichen Höfe von Eldre'Thalas eingenommen. Besiege König Gordok und hol dir ihren Tribut.",
            DMW = "Im Westflügel zapfen die Hochgeborenen von Eldre'Thalas unter Prinz Tortheldrin die Macht des Dämons Immol'thar ab.",
            DROWNED = "Versunkene Trollruinen sind vor der Küste des Schlingendorntals aus dem Meer aufgetaucht, und Trolle, Naga und Piraten kämpfen um das, was darin liegt.",
            EXC = "Eine Ausgrabung der Forscherliga ist auf uralte Hallen der Titanen gestoßen: seltsamer Nebel, Lichtblitze und Konstrukte, die noch immer Wache halten.",
            GNOMER = "Die verstrahlte Hauptstadt der Gnome, die durch die Troggs und den Verrat von Robogenieur Thermaplugg verloren ging.",
            HOT = "Dunkeleisenzwerge sind in die königlichen Gräber der alten Thanen der Zwerge unter der Altstadt von Ironforge eingebrochen, und die ruhelosen Toten sind erwacht.",
            HYJAL = "Etwas entzieht dem Land rund um den Berg Hyjal seine Kraft, und noch immer wandeln dort Geister aus dem Dritten Krieg.",
            KROLDOK = "Eine riesige Festung der Oger, deren Plünderer Gefangene machen und deren nächtliche Gesänge auf den Twilight-Hammer hindeuten.",
            LBRS = "Die unteren Hallen der Blackrockspitze, eine Festung der Orcs und Oger unter Oberanführer Wyrmthalak. In Forever für zehn Spieler.",
            MARA = "Eine heilige Höhle der Zentauren in Desolace, verderbt von Prinzessin Theradras, einem Elementarwesen der Erde.",
            ONY = "Onyxia, die Tochter von Deathwing, wartet in ihrem Hort in den Marschen von Dustwallow. Wird mit dem ersten Raid-Tier von Forever freigeschaltet.",
            RFC = "Vulkanische Höhlen unter Orgrimmar, in denen Troggs und der Kult der Burning Blade aus dem Verborgenen gegen die Horde intrigieren.",
            RFD = "Die uralten Begräbnisstätten der Stacheleber sind an die Geißel gefallen, angeführt vom Lich Amnennar dem Kältebringer.",
            RFK = "Ein dorniges Labyrinth im südlichen Brachland, Heimat der Stacheleber und ihrer Anführerin Charlga Razorflank, einer Priesterin der Totenköpfe.",
            ROL = "Die Geißel hält noch immer die zerstörte Hauptstadt über Undercity, wo ein Nekromant in der Asche von Lordaeron Macht sammelt.",
            SCHOLO = "Die Schule der Nekromantie in den Grüften unter Caer Darrow, geleitet von Dunkelmeister Gandling.",
            SFK = "Erzmagier Arugal und seine Worgen halten die Burg über Pyrewood, und der Fluch von Shadowfang breitet sich immer weiter aus.",
            SHAPER = "Eine unberührte Anlage der Titanen in den Hügeln des Un'Goro-Kraters, erfüllt vom Summen der Machtkristalle und von einer Kraft, die niemand erklären kann.",
            SMARM = "Herod, der Scharlachrote Held, wacht über das Arsenal des Kreuzzugs.",
            SMCATH = "Im Herzen des Klosters führen Kommandant Mograine und Hochinquisitor Whitemane die Fanatiker an.",
            SMGY = "Ruhelose Kreuzritter spuken auf dem Friedhof des Klosters, auf dem Blutmagier Thalnos noch immer umgeht.",
            SMLIB = "Hundemeister Loksey und Arkanist Doan hüten die verbotenen Folianten des Scharlachroten Kreuzzugs.",
            ST = "Der versunkene Tempel von Atal'Hakkar, in dem die Trolle der Atal'ai den Blutgott Hakkar beschwören wollen.",
            STOCKS = "Im Gefängnis von Stormwind herrscht Chaos: Gefangene Defias unter Bazil Thredd haben die Zellenblöcke übernommen.",
            STRATLIVE = "Der Scharlachrote Kreuzzug verteidigt die brennenden Straßen hinter dem Haupttor von Stratholme gegen die Geißel.",
            STRATUD = "Hinter dem Dienstboteneingang herrscht Baron Rivendare über die von der Geißel besetzte Hälfte von Stratholme.",
            UBRS = "Die oberen Bereiche der Blackrockspitze, wo Rend Blackhand und General Drakkisath die Streitkräfte des schwarzen Drachenschwarms befehligen. In Forever für zehn Spieler.",
            ULDA = "Ein uraltes Gewölbe der Titanen im Ödland, umkämpft von Dunkeleisenzwergen, Troggs und dem steinernen Wächter Archaedas.",
            WC = "Tief unter dem Brachland bewachen die Druiden des Giftzahns den träumenden Naralex, dessen Alptraum die Höhlen und alles darin verzerrt hat.",
            ZF = "Die sonnenverbrannte Trollstadt der Sandfury in Tanaris, beherrscht von Häuptling Ukorz Sandscalp.",
        },
