            ["Saved item data: %d items, %d not available in this game version (loaded from the last session: %d)"] = "Gespeicherte Gegenstandsdaten: %d Gegenstände, %d in dieser Spielversion nicht verfügbar (aus der letzten Sitzung geladen: %d)",
            ["Says when the item is on your wishlist."] = "Zeigt an, wenn der Gegenstand auf deiner Wunschliste steht.",
            ["Search"] = "Suche",
            ["Search all items you can wear"] = "Alles suchen, was du tragen kannst",
            ["Search and sort"] = "Suchen und sortieren",
            ["Search any item, boss, rare or quest here. The results show as you type."] = "Suche hier nach jedem Gegenstand, Boss, Rare oder jeder Quest. Die Ergebnisse erscheinen beim Tippen.",
            ["Search dungeons, raids, zones"] = "Dungeons, Schlachtzüge, Gebiete suchen",
            ["Search items, bosses, quests"] = "Gegenstände, Bosse, Quests suchen",
            ["Search items, slots, sources"] = "Gegenstände, Plätze, Quellen suchen",
            ["Search mobs, bosses, places"] = "Mobs, Bosse, Orte suchen",
            ["Search name or source"] = "Name oder Quelle suchen",
            ["Search quests, givers, places"] = "Quests, Questgeber, Orte suchen",
            ["Select a quest to see what you need to do and where it starts."] = "Wähle eine Quest, um zu sehen, was zu tun ist und wo sie beginnt.",
            ["Set %d"] = "Set %d",
            ["Set %s DPS"] = "Set %s DPS",
            ["Sets"] = "Sets",
            ["Settings"] = "Einstellungen",
            ["Shadow"] = "Schatten",
            ["Shadow Spell Power"] = "Schattenzaubermacht",
            ["Shaman"] = "Schamane",
            ["Shield"] = "Schild",
            ["Shields & Off-hands"] = "Schilde & Schildhand",
            ["Shift into Bear Form, then try again: the simulator reads your bear's numbers."] = "Verwandle dich in Bärengestalt und versuch es dann nochmal: der Simulator liest die Werte deines Bären.",
            ["Shift into Cat Form, then try again: the simulator reads your cat's numbers."] = "Verwandle dich in Katzengestalt und versuch es dann nochmal: der Simulator liest die Werte deiner Katze.",
            ["Shift-click to remove every item."] = "Umschalt-Klick entfernt alle Gegenstände.",
            ["Shirt"] = "Hemd",
            ["Short words match hundreds of items, so the search starts at 3 letters. Dungeon shortcuts like \"dm\" or \"zf\" work right away."] = "Kurze Wörter passen auf Hunderte Gegenstände, daher startet die Suche ab 3 Buchstaben. Dungeon-Kürzel wie \"dm\" oder \"zf\" gehen sofort.",
            ["Shoulder"] = "Schulter",
            ["Show all results"] = "Alle Ergebnisse anzeigen",
            ["Show dungeon map"] = "Dungeonkarte zeigen",
            ["Show fewer"] = "Weniger zeigen",
            ["Show on map"] = "Auf der Karte zeigen",
            ["Show on the map"] = "Auf der Karte zeigen",
            ["Show quest: %s"] = "Quest zeigen: %s",
            ["Show source: %s"] = "Quelle zeigen: %s",
            ["Show the entrance"] = "Eingang zeigen",
            ["Show the quest giver on the map"] = "Questgeber auf der Karte zeigen",
            ["Shows the entrance on the world map."] = "Zeigt den Eingang auf der Weltkarte.",
            ["Shows the item on your character in the dressing room."] = "Zeigt den Gegenstand an deinem Charakter in der Anprobe.",
            ["Silver"] = "Silber",
            ["Sim"] = "Sim",
            ["Sim %d%%"] = "Sim %d%%",
            ["Sim my gear"] = "Sim: meine Ausrüstung",
            ["Sim my set"] = "Sim: mein Set",
            ["Sim outdated"] = "Sim veraltet",
            ["Sim speed"] = "Sim-Tempo",
            ["Sim the sets"] = "Sim: die Sets",
            ["Sim this set"] = "Dieses Set simmen",
            ["Sim this set for its DPS"] = "Simme dieses Set für seine DPS",
            ["Sim: every upgrade in DPS from the simulator, for players who want to run sims themselves."] = "Sim: jede Verbesserung in DPS aus dem Simulator, für Spieler, die selbst simmen wollen.",
            ["Sim: it fights against what you wear."] = "\"Sim\": Er kämpft gegen das, was du trägst.",
            ["Sim: no item adds damage"] = "Sim: nichts bringt mehr Schaden",
            ["Sim: what you wear is best"] = "Sim: was du trägst, ist am besten",
            ["Simming ..."] = "Simuliere ...",
            ["Simming: %d%%"] = "Simuliere: %d%%",
            ["Simming: %s"] = "Simuliere: %s",
            ["Sims the tab you see against the target and for the fight length at the top right: \"%s\" on Character, \"%s\" in the Planner, \"%s\" on Sets. While it sims, it stops it."] = "Simuliert den Tab, den du siehst, gegen das Ziel und für die Kampfdauer oben rechts: „%s“ bei Charakter, „%s“ im Planer, „%s“ bei Sets. Während er simuliert, hält er ihn an.",
            ["Simulate"] = "Simulieren",
            ["Simulator"] = "Simulator",
            ["Skip tour"] = "Tour überspringen",
            ["Slot"] = "Platz",
            ["Slots"] = "Plätze",
            ["Smooth"] = "Flüssig",
            ["Smooth: %d ms per frame, the game stays the smoothest."] = "Flüssig: %d ms pro Bild, das Spiel bleibt am flüssigsten.",
            ["Sort: %s"] = "Sortierung: %s",
            ["Source"] = "Quelle",
            ["Sources"] = "Quellen",
            ["Spec"] = "Spezialisierung",
            ["Spell Damage"] = "Zauberschaden",
            ["Spell Power"] = "Zaubermacht",
            ["Spell crit · hit"] = "Zauberkrit · Zaubertreffer",
            ["Spirit"] = "Willenskraft",
            ["Staff"] = "Stab",
            ["Stamina"] = "Ausdauer",
            ["Standard (Percent)"] = "Standard (Prozent)",
            ["Star items to see which dungeons, bosses and rares to run."] = "Markiere Gegenstände, um zu sehen, welche Dungeons, Bosse und Rares du laufen solltest.",
            ["Start from"] = "Starten mit",
            ["Start the Best in Slot sim here: it builds your list from every item you can wear while you take the tour (a few minutes)."] = "Starte hier den Best-in-Slot-Sim: Er erstellt deine Liste aus jedem Gegenstand, den du tragen kannst, während du die Tour machst (ein paar Minuten).",
            ["Start the tour"] = "Tour starten",
            ["Starts the quest"] = "Startet die Quest",
            ["Stat priority"] = "Stat-Prio",
            ["Stats for %s"] = "Werte für %s",
            ["Status"] = "Status",
            ["Step %d of %d: %s"] = "Schritt %d von %d: %s",
            ["Still collecting, please wait for the result line."] = "Sammle noch, bitte warte auf die Ergebniszeile.",
            ["Stop"] = "Stopp",
            ["Stopped."] = "Gestoppt.",
            ["Strength"] = "Stärke",
            ["Subtlety"] = "Täuschung",
            ["Survival"] = "Überleben",
            ["Switch it on for your Best in Slot set, the next upgrades, the simulator and the upgrade check for loot. The settings have it too (Modules)."] = "Schalte es ein für dein Best-in-Slot-Set, die nächsten Verbesserungen, den Simulator und den Verbesserungs-Check für Beute. Du findest es auch in den Einstellungen (Module).",
            ["Switch off the pages you do not use. Best in Slot and Wishlist also take their marks, tooltip lines and alerts with them. One module always stays on."] = "Schalte die Seiten ab, die du nicht nutzt. Best in Slot und Wunschliste nehmen auch ihre Markierungen, Tooltip-Zeilen und Hinweise mit. Ein Modul bleibt immer an.",
            ["Switch off what you do not use: its tab goes away, Best in Slot also takes its crowns and tooltip lines with it, Wishlist its stars, tooltip mark and alerts. One module always stays on. The database look has its own pages."] = "Schalte ab, was du nicht brauchst: sein Tab verschwindet, Best in Slot nimmt auch seine Kronen und Tooltip-Zeilen mit, die Wunschliste ihre Sterne, ihre Tooltip-Markierung und ihre Hinweise. Ein Modul bleibt immer an. Der Datenbank-Look hat eigene Seiten.",
            ["Switch on Best in Slot"] = "Best in Slot einschalten",
            ["Sword"] = "Schwert",
            ["TANK"] = "TANK",
            ["TURN IN"] = "ABGABE",
            ["Tabard"] = "Wappenrock",
            ["Tailoring"] = "Schneiderei",
            ["Taken from the English collect, not asked: %d items without data, %d refused quests."] = "Aus dem englischen Collect übernommen, nicht gefragt: %d Gegenstände ohne Daten, %d abgelehnte Quests.",
            ["Takes every item out of this set."] = "Nimmt alle Gegenstände aus diesem Set.",
            ["Talents the sim plays itself: %s."] = "Talente, die der Sim selbst spielt: %s.",
            ["Tanks wear their heaviest armor."] = "Tanks tragen ihre schwerste Rüstung.",
            ["Target"] = "Ziel",
            ["Teal"] = "Türkis",
            ["The Best in Slot module is off (Modules)."] = "Das Modul Best in Slot ist aus (Module).",
            ["The Best in Slot sim is running: the small window shows how far it is. Take the tour meanwhile; your list is ready when it is done."] = "Der Best-in-Slot-Sim läuft: Das kleine Fenster zeigt, wie weit er ist. Mach solange die Tour; deine Liste ist fertig, wenn er fertig ist.",
            ["The Journal module is off (Modules)."] = "Das Modul Journal ist aus (Module).",
            ["The Underbelly"] = "Die Schattenseite",
            ["The Wishlist module is off (Modules)."] = "Das Modul Wunschliste ist aus (Module).",
            ["The boss, rare or zone that drops it, with the chance."] = "Der Boss, der Rare oder die Zone, wo er droppt, mit der Chance.",
            ["The bosses and their loot are added as soon as they are seen in the game or revealed."] = "Die Bosse und ihre Beute werden ergänzt, sobald sie im Spiel gesehen oder enthüllt werden.",
            ["The damage the sim found for the item against what you wear, or that it is on your Best in Slot list."] = "Der Schaden, den der Sim für den Gegenstand gegen das gefunden hat, was du trägst, oder dass er auf deiner Best-in-Slot-Liste steht.",
            ["The dungeon entrances on the world map, the alert when a wishlist item drops and opening the dungeon you are in."] = "Die Dungeon-Eingänge auf der Weltkarte, der Hinweis, wenn ein Wunschlisten-Gegenstand droppt, und das Öffnen des Dungeons, in dem du bist.",
            ["The filter of your Best in Slot list: the spec it is made for, the armor it takes and where its items may come from. Open it any time: the first time it explains itself."] = "Der Filter deiner Best-in-Slot-Liste: die Spezialisierung, für die sie gemacht ist, die Rüstung, die sie nimmt, und woher ihre Gegenstände kommen dürfen. Öffne ihn jederzeit: Beim ersten Mal erklärt er sich selbst.",
            ["The filter of your Best in Slot list: the spec it is made for, the armor it takes and where its items may come from; its second tab orders your stats. Open it any time: the first time it explains itself."] = "Der Filter deiner Best-in-Slot-Liste: die Spezialisierung, für die sie gemacht ist, die Rüstung, die sie nimmt, und woher ihre Gegenstände kommen dürfen; sein zweiter Tab ordnet deine Werte. Öffne ihn jederzeit: Beim ersten Mal erklärt er sich selbst.",
            ["The game blocked an action of Lootified (%s). /lf errors shows the details."] = "Das Spiel hat eine Aktion von Lootified blockiert (%s). /lf errors zeigt die Details.",
            ["The game does not let addons open the world map right now."] = "Das Spiel lässt Addons die Weltkarte gerade nicht öffnen.",
            ["The game does not let addons open the world map right now. The spot is marked: open your world map to see it."] = "Das Spiel lässt Addons die Weltkarte gerade nicht öffnen. Die Stelle ist markiert: Öffne deine Weltkarte, um sie zu sehen.",
            ["The game has no data of this item yet: press Sim again in a moment."] = "Das Spiel hat noch keine Daten zu diesem Gegenstand: Drück gleich noch einmal auf \"Sim\".",
            ["The game has no map data for the open world mobs yet."] = "Das Spiel hat noch keine Kartendaten für die Mobs der offenen Welt.",
            ["The game has no map position for this spot."] = "Das Spiel hat für diesen Ort keine Kartenposition.",
            ["The game has not sent all of its data yet."] = "Das Spiel hat noch nicht alle Daten geschickt.",
            ["The game is still loading your spell texts: try again in a moment."] = "Das Spiel lädt deine Zaubertexte noch: versuch es gleich nochmal.",
            ["The gear button at the top right opens the settings. Pick a category on the left; every change applies at once."] = "Der Zahnrad-Button oben rechts öffnet die Einstellungen. Wähle links eine Kategorie; jede Änderung gilt sofort.",
            ["The green arrow marks the items of your Best in Slot list (sort by For you to see the best first)."] = "Der grüne Pfeil markiert die Gegenstände deiner Best-in-Slot-Liste (sortiere nach Für dich, um die besten zuerst zu sehen).",
            ["The green arrow marks the items of your Best in Slot list, with the damage they add (sort by For you to see the biggest first)."] = "Der grüne Pfeil markiert die Gegenstände deiner Best-in-Slot-Liste, mit dem Schaden, den sie bringen (sortiere nach Für dich, um die größten zuerst zu sehen).",
            ["The items you starred, grouped by where they drop. You get an alert as soon as one drops."] = "Die Gegenstände mit Stern, gruppiert nach ihrer Quelle. Du bekommst einen Hinweis, sobald einer droppt.",
            ["The items you starred; the stars, the tooltip mark and the alert when one drops."] = "Die Gegenstände, die du markiert hast; die Sterne, die Tooltip-Markierung und der Hinweis, wenn einer droppt.",
            ["The language is under Language; this tour starts again from Tour & help or with /lf tour. Found a bug or have an idea? Website & Discord are here and behind the ? at the top. Have fun!"] = "Die Sprache findest du unter Sprache; diese Tour startet wieder über Tour & Hilfe oder mit /lf tour. Einen Fehler gefunden oder eine Idee? Website & Discord findest du hier und hinter dem ? oben. Viel Spaß!",
            ["The language of the interface and of the game's names in Lootified."] = "Die Sprache der Oberfläche und der Namen aus dem Spiel in Lootified.",
            ["The last collect was cut off: what it had read is kept. /lf collect again reads the rest."] = "Die letzte Sammlung wurde abgebrochen: Was sie gelesen hatte, bleibt erhalten. Ein neues /lf collect liest den Rest.",
            ["The level of the target dummy. It stands still, never hits back and is hit from behind."] = "Die Stufe der Trainingspuppe. Sie steht still, schlägt nie zurück und wird von hinten angegriffen.",
            ["The lines Lootified adds to item tooltips, one switch each. The preview shows a real tooltip as you set it."] = "Die Zeilen, die Lootified Gegenstands-Tooltips hinzufügt, jede mit eigenem Schalter. Die Vorschau zeigt einen echten Tooltip, so wie du ihn einstellst.",
            ["The list of the first start: every armor your class wears, quests, dungeons and rares, drops of 10 % or more."] = "Die Liste vom ersten Start: jede Rüstung deiner Klasse, Quests, Dungeons und Rares, Drops ab 10 %.",
            ["The loot of the dungeons' and raids' bosses and trash."] = "Die Beute der Bosse und des Trashs in Dungeons und Raids.",
            ["The loot of the open world's rares and other mobs that carry the item."] = "Die Beute der Rares und anderer Mobs der offenen Welt, die den Gegenstand tragen.",
            ["The picked item: its stats and where it drops (click a mob or a quest to open it)."] = "Der gewählte Gegenstand: seine Werte und wo er droppt (klicke auf einen Mob oder eine Quest, um sie zu öffnen).",
            ["The picked item: its stats, where it drops (click a mob or a quest to open it) and the wishlist button. You get an alert when a wishlist item drops."] = "Der gewählte Gegenstand: seine Werte, wo er droppt (klicke auf einen Mob oder eine Quest, um sie zu öffnen) und der Wunschlisten-Button. Du bekommst einen Hinweis, wenn ein Gegenstand der Wunschliste droppt.",
            ["The quests that give the item or need it."] = "Die Quests, die den Gegenstand geben oder brauchen.",
            ["The rares and mobs of every zone with their drops and camps."] = "Die Rares und Gegner jeder Zone mit ihrer Beute und ihren Lagern.",
            ["The rares and other mobs of every zone with their drops, drop chances and camps on the map. The page shows the zone you are in."] = "Die Rares und anderen Mobs jeder Zone mit ihrer Beute, Dropchancen und Lagern auf der Karte. Die Seite zeigt die Zone, in der du bist.",
            ["The same for bosses and rares, for quests (with their chains) and for dungeons, raids and zones. Links between the pages open the right entry."] = "Dasselbe für Bosse und Rares, für Quests (mit ihren Questreihen) und für Dungeons, Schlachtzüge und Gebiete. Links zwischen den Seiten öffnen den passenden Eintrag.",
            ["The set fights in the simulator's planner for its exact damage: the number on the sheet is an estimate from each item simmed alone."] = "Das Set kämpft im Planer des Simulators für seinen genauen Schaden: Die Zahl auf dem Bogen ist eine Schätzung aus den einzeln gesimmten Gegenständen.",
            ["The simulator could not read your character: %s"] = "Der Simulator konnte deinen Charakter nicht lesen: %s",
            ["The simulator fights with your talents and gear and shows every upgrade in DPS. You run the sims yourself (the Best in Slot sim takes a few minutes): pick it only if you want that."] = "Der Simulator kämpft mit deinen Talenten und deiner Ausrüstung und zeigt jede Verbesserung in DPS. Die Sims startest du selbst (der Best-in-Slot-Sim dauert ein paar Minuten): Nimm das nur, wenn du das willst.",
            ["The simulator has no numbers for this item."] = "Der Simulator hat keine Werte für diesen Gegenstand.",
            ["The simulator is calculating"] = "Der Simulator rechnet",
            ["The simulator rates your damage. Your upgrades follow your stat weights."] = "Der Simulator bewertet deinen Schaden. Deine Verbesserungen richten sich nach deiner Stat-Gewichtung.",
            ["The simulator stopped: %s"] = "Der Simulator wurde angehalten: %s",
            ["The target: %s"] = "Das Ziel: %s",
            ["The tour stopped because of combat. /lf tour starts it again."] = "Die Tour wurde wegen eines Kampfes beendet. /lf tour startet sie erneut.",
            ["These are the bosses, numbered in their order. Click one to see its loot next to the map; click it again to close it."] = "Das sind die Bosse, nummeriert in ihrer Reihenfolge. Klicke auf einen, um seine Beute neben der Karte zu sehen; ein zweiter Klick schließt sie wieder.",
            ["This decides how this character's upgrades show in tooltips, loot rolls, For you and its Best in Slot list."] = "Das bestimmt, wie die Verbesserungen dieses Charakters in Tooltips, bei Würfelwürfen um Beute, in Für dich und in seiner Best-in-Slot-Liste angezeigt werden.",
            ["This dungeon has more than one floor: switch between them here. Next to the buttons is the name of the floor you see."] = "Dieser Dungeon hat mehrere Ebenen: Hier wechselst du zwischen ihnen. Neben den Knöpfen steht der Name der Ebene, die du gerade siehst.",
            ["This is For you, your start page: the dungeons for your level with your upgrades and your next Best in Slot items. Click anything to open it."] = "Das ist Für dich, deine Startseite: die Dungeons für deine Stufe mit deinen Verbesserungen und deine nächsten BiS-Teile. Klicke auf etwas, um es zu öffnen.",
            ["This is For you, your start page: the dungeons for your level. Click anything to open it."] = "Das ist Für dich, deine Startseite: die Dungeons für deine Stufe. Klicke auf etwas, um es zu öffnen.",
            ["This item is not in the loot data. It may be crafted, sold by a vendor or come from a source that is new in Forever."] = "Dieser Gegenstand ist nicht in den Beutedaten. Er ist evtl. hergestellt, beim Händler erhältlich oder stammt aus einer Quelle, die in Forever neu ist.",
            ["This item is not in your game client yet (datamined / upcoming)."] = "Dieser Gegenstand ist noch nicht in deinem Spielclient (gedatamined / kommt noch).",
            ["This spec fights in Bear Form, which druids learn at level 10. Until then, pick another spec on the Best in Slot sheet."] = "Diese Spezialisierung kämpft in Bärengestalt, die Druiden ab Stufe 10 lernen. Wähle bis dahin eine andere Spezialisierung auf der Best-in-Slot-Seite.",
            ["This spec fights in Cat Form, which druids learn at level 20. Until then, pick another spec on the Best in Slot sheet."] = "Diese Spezialisierung kämpft in Katzengestalt, die Druiden ab Stufe 20 lernen. Wähle bis dahin eine andere Spezialisierung auf der Best-in-Slot-Seite.",
            ["This spec fights in Defensive Stance, which warriors learn at level 10. Until then, pick another spec on the Best in Slot sheet."] = "Diese Spezialisierung kämpft in Verteidigungshaltung, die Krieger ab Stufe 10 lernen. Wähle bis dahin eine andere Spezialisierung auf der Best-in-Slot-Seite.",
            ["This spec fights with a pet, which hunters get at level 10. Until then, pick another spec on the Best in Slot sheet."] = "Diese Spezialisierung kämpft mit einem Tier, das Jäger ab Stufe 10 bekommen. Wähle bis dahin eine andere Spezialisierung auf der Best-in-Slot-Seite.",
            ["This spec tanks with a shield: put one on, then try again."] = "Diese Spezialisierung tankt mit Schild: leg einen an und versuch es dann nochmal.",
            ["This tour shows every part of Lootified. At the end you see the settings, where you can switch off what you do not need."] = "Diese Tour zeigt jeden Teil von Lootified. Am Ende siehst du die Einstellungen, wo du abschalten kannst, was du nicht brauchst.",
            ["Thrown"] = "Wurfwaffe",
            ["Tooltips"] = "Tooltips",
            ["Totem"] = "Totem",
            ["Tour & help"] = "Tour & Hilfe",
            ["Trade Goods (Parts)"] = "Handwerkswaren (Teile)",
            ["Trash"] = "Trash",
            ["Trash & zone drops"] = "Trash & Gebietsdrops",
            ["Trash mobs"] = "Trash",
            ["Trinket"] = "Schmuck",
            ["Try on"] = "Anprobieren",
            ["Try on set (Dressing Room)"] = "Set anprobieren (Anprobe)",
            ["Try the name of a dungeon, boss, quest, zone, mob or item. Parts of words work too, e.g. \"vanc\" or \"blade\"."] = "Versuch den Namen eines Dungeons, Bosses, einer Quest, eines Gebiets, Mobs oder Gegenstands. Wortteile gehen auch, z. B. \"vanc\" oder \"klinge\".",
            ["Turbo"] = "Turbo",
            ["Turbo: %d ms per frame, the sim is done soonest, the game can run slower meanwhile."] = "Turbo: %d ms pro Bild, der Sim ist am schnellsten fertig, das Spiel kann solange langsamer laufen.",
            ["Turn in"] = "Abgabe",
            ["Two sets of your own: click a slot to pick any item your character can put on there, or drop an item from your bags on it. The set fights on its own."] = "Zwei eigene Sets: Klick auf einen Platz und wähle jeden Gegenstand, den dein Charakter dort anlegen kann, oder zieh einen Gegenstand aus deinen Taschen darauf. Das Set kämpft für sich allein.",
            ["Two-Hand"] = "Zweihändig",
            ["Two-hand weapon"] = "Zweihandwaffe",
            ["Two-hander in the main hand"] = "Zweihänder in der Waffenhand",
            ["Type"] = "Typ",
            ["Type /lf collect stop to cancel. Please stay logged in."] = "Mit /lf collect stop abbrechen. Bitte eingeloggt bleiben.",
            ["Type /reload, then send the file WTF\\Account\\<account>\\SavedVariables\\Lootified.lua."] = "Gib /reload ein und schicke dann die Datei WTF\\Account\\<Account>\\SavedVariables\\Lootified.lua.",
            ["Type a name, a slot or a place: the list follows as you type. The switch beside it and Sort change what shows and in which order."] = "Tippe einen Namen, einen Platz oder einen Ort: Die Liste folgt beim Tippen. Der Schalter daneben und die Sortierung ändern, was erscheint und in welcher Reihenfolge.",
            ["Type at least 3 letters"] = "Gib mindestens 3 Buchstaben ein",
            ["Uncommon"] = "Ungewöhnlich",
            ["Unknown"] = "Unbekannt",
            ["Up to date"] = "Aktuell",
            ["Upgrade"] = "Verbesserung",
            ["Upgrade check for loot"] = "Verbesserungs-Check für Beute",
            ["Upgrade for my spec"] = "Verbesserung für meine Spezialisierung",
            ["Upgrade for you"] = "Verbesserung für dich",
            ["Upgrade for you: %s"] = "Verbesserung für dich: %s",
            ["Upgrades for you"] = "Verbesserungen für dich",
            ["Upgrades only"] = "Nur Verbesserungen",
            ["Usable by me"] = "Für mich nutzbar",
            ["Usable from level %d"] = "Nutzbar ab Stufe %d",
            ["Usage: /lf collect, /lf collect language, /lf collect stop or /lf collect clear."] = "Aufruf: /lf collect, /lf collect language, /lf collect stop oder /lf collect clear.",
            ["Use %d %s"] = "Benutze %d %s",
            ["Use Advanced"] = "Erweitert nutzen",
            ["Use Percent"] = "Prozent nutzen",
            ["Use Percent?"] = "Prozent nutzen?",
            ["Use Standard"] = "Standard nutzen",
            ["Use this look"] = "Dieses Aussehen nehmen",
            ["Version %s"] = "Version %s",
            ["Violet"] = "Violett",
            ["WORLD DROP"] = "WELTDROP",
            ["Waist"] = "Taille",
            ["Wand"] = "Zauberstab",
            ["Warlock"] = "Hexenmeister",
            ["Warrior"] = "Krieger",
            ["Weapon skill"] = "Waffenfertigkeit",
            ["Weapons"] = "Waffen",
            ["Website & Discord"] = "Website & Discord",
            ["Welcome to Lootified"] = "Willkommen bei Lootified",
            ["Welcome to Lootified! How should the window look?"] = "Willkommen bei Lootified! Wie soll das Fenster aussehen?",
            ["Welcome to the Database"] = "Willkommen in der Datenbank",
            ["What I wear"] = "Was ich trage",
            ["What is collected so far is saved with the next /reload."] = "Was bisher gesammelt wurde, wird beim nächsten /reload gespeichert.",
            ["What one more point is worth"] = "Was ein Punkt mehr bringt",
            ["What you wear"] = "Was du trägst",
            ["What you wear, your Best in Slot sheet and your own sets side by side, all in the same fights."] = "Was du trägst, deine Best-in-Slot-Liste und deine eigenen Sets im Vergleich, alle in denselben Kämpfen.",
            ["What your Best in Slot list may use"] = "Was deine Best-in-Slot-Liste nutzen darf",
            ["What your list may use: the armor kinds (cloaks always count) and where its items may come from. The drop chance leaves out rarer drops (10 % at the start). Every change counts at once, for the sims too; Back to realistic gives back the list of your first start."] = "Was deine Liste nutzen darf: die Rüstungsarten (Umhänge zählen immer) und woher ihre Gegenstände kommen dürfen. Die Drop-Chance lässt seltenere Drops weg (am Anfang 10 %). Jede Änderung zählt sofort, auch für die Sims; „Zurück zu realistisch“ stellt die Liste deines ersten Starts wieder her.",
            ["What your list may use: where its items may come from. The drop chance leaves out rarer drops (10 % at the start). Every change counts at once, for the sims too; Back to realistic gives back the list of your first start."] = "Was deine Liste nutzen darf: woher ihre Gegenstände kommen dürfen. Die Drop-Chance lässt seltenere Drops weg (am Anfang 10 %). Jede Änderung zählt sofort, auch für die Sims; „Zurück zu realistisch“ stellt die Liste deines ersten Starts wieder her.",
            ["Where"] = "Wo",
            ["Where it comes from"] = "Woher es kommt",
            ["Where it drops"] = "Wo er droppt",
            ["Where the difference comes from"] = "Woher der Unterschied kommt",
            ["Where to go"] = "Wohin gehen",
            ["Window position"] = "Fensterposition",
            ["Window position and scale reset."] = "Fensterposition und Größe zurückgesetzt.",
            ["Window size"] = "Fenstergröße",
            ["Wishlist"] = "Wunschliste",
            ["Wishlist cleared."] = "Wunschliste geleert.",
            ["Wishlist mark"] = "Wunschlisten-Markierung",
            ["With upgrades for me"] = "Mit Verbesserungen für mich",
            ["Without a choice, Lootified rates your items in Percent. You can change it any time in the settings (the sliders icon, General)."] = "Ohne Auswahl bewertet Lootified deine Gegenstände in Prozent. Du kannst es jederzeit in den Einstellungen ändern (das Regler-Symbol, Allgemein).",
            ["World"] = "Welt",
            ["World drop"] = "Weltdrop",
            ["World drop - level %s"] = "Weltdrop - Stufe %s",
            ["Wrist"] = "Handgelenke",
            ["You are here"] = "Du bist hier",
            ["You are level %d."] = "Du bist Level %d.",
            ["You can change how items are rated any time in the settings (the sliders icon, General)."] = "Wie Gegenstände bewertet werden, kannst du jederzeit in den Einstellungen ändern (das Regler-Symbol, Allgemein).",
            ["You can change it any time in the options (the sliders icon) or with /lf look."] = "Du kannst es jederzeit in den Optionen (das Regler-Symbol) oder mit /lf look ändern.",
            ["You can change it any time in the settings (the sliders icon, General)."] = "Du kannst es jederzeit in den Einstellungen ändern (das Regler-Symbol, Allgemein).",
            ["You cannot dual wield."] = "Du kannst nicht beidhändig kämpfen.",
            ["You get an alert when it drops."] = "Du bekommst einen Hinweis, wenn er droppt.",
            ["You wear it"] = "Trägst du schon",
            ["You, as the sim read you"] = "Du, wie die Sim dich liest",
            ["Your Best in Slot items are already owned or on your wishlist."] = "Deine Best-in-Slot-Gegenstände sind bereits im Besitz oder auf deiner Wunschliste.",
            ["Your Best in Slot list is only an estimate so far. The sim tests every item you can wear on your character (a few minutes), then your next upgrades show here."] = "Deine Best-in-Slot-Liste ist bisher nur geschätzt. Der Sim testet mit deinem Charakter jeden Gegenstand, den du tragen kannst (ein paar Minuten), danach stehen hier deine nächsten Verbesserungen.",
            ["Your Best in Slot list on your character, from the stat weights of your spec. An item's tooltip says where it drops."] = "Deine Best-in-Slot-Liste an deinem Charakter, aus der Stat-Gewichtung deiner Spezialisierung. Der Tooltip eines Gegenstands sagt, wo er droppt.",
            ["Your Best in Slot list on your character: the Best in Slot sim builds it from every item you can wear. An item's tooltip says where it drops."] = "Deine Best-in-Slot-Liste an deinem Charakter: Der Best-in-Slot-Sim erstellt sie aus jedem Gegenstand, den du tragen kannst. Der Tooltip eines Gegenstands sagt, wo er droppt.",
            ["Your Best in Slot set"] = "Dein Best-in-Slot-Set",
            ["Your best gear for every slot, the simulator, the crowns on items, the tooltip line and the upgrade check for loot."] = "Deine beste Ausrüstung für jeden Platz, der Simulator, die Kronen an Gegenständen, die Tooltip-Zeile und der Verbesserungs-Check für Beute.",
            ["Your character as the simulator reads it: gear, stats, spells, talents and pet. Press Ctrl+C to copy it, then paste it into Lootified's web simulator."] = "Dein Charakter, wie der Simulator ihn liest: Ausrüstung, Werte, Zauber, Talente und Tier. Drück Strg+C zum Kopieren und füge ihn dann in Lootifieds Web-Simulator ein.",
            ["Your character as you wear it: your damage per second, the damage of every ability, what one more point of each stat is worth and what the sim read from you and the target."] = "Dein Charakter, so wie er ausgerüstet ist: dein Schaden pro Sekunde, der Schaden jeder Fähigkeit, was ein Punkt mehr von jedem Wert bringt und was der Sim von dir und dem Ziel gelesen hat.",
            ["Your character cannot wear this item."] = "Dein Charakter kann diesen Gegenstand nicht tragen.",
            ["Your character's damage, your own sets in the planner and the sets side by side."] = "Der Schaden deines Charakters, deine eigenen Sets im Planer und die Sets im Vergleich.",
            ["Your class cannot use it"] = "Nicht für deine Klasse",
            ["Your class wears it from level %d."] = "Deine Klasse trägt sie ab Stufe %d.",
            ["Your crit against it"] = "Dein Krit gegen das Ziel",
            ["Your damage"] = "Dein Schaden",
            ["Your gear right now."] = "Deine Ausrüstung jetzt.",
            ["Your last sim, with other gear, talents, level or fight settings: press Sim for new numbers."] = "Dein letzter Sim, mit anderer Ausrüstung, anderen Talenten, Stufe oder Kampf-Einstellung: Drück auf \"Sim\" für neue Zahlen.",
            ["Your level, talents or gear changed since the last sim: sim again for a list that fits."] = "Deine Stufe, Talente oder Ausrüstung haben sich seit dem letzten Sim geändert: Simuliere neu für eine passende Liste.",
            ["Your level, talents, gear or list changed since the last sim: sim again for a list that fits."] = "Deine Stufe, Talente, Ausrüstung oder Liste haben sich seit dem letzten Sim geändert: Simuliere neu für eine passende Liste.",
            ["Your list takes armor of this kind from head to feet; cloaks always count."] = "Deine Liste nimmt Rüstung dieser Art von Kopf bis Fuß; Umhänge zählen immer.",
            ["Your list was simmed with your level, talents and the gear you wear: no new sim needed. A click sims it again all the same."] = "Deine Liste wurde mit deiner Stufe, deinen Talenten und deiner jetzigen Ausrüstung simuliert: Ein neuer Sim ist nicht nötig. Ein Klick simuliert sie trotzdem neu.",
            ["Your name and realm are not in it. Export again after you change your gear or talents."] = "Dein Name und dein Realm stehen nicht drin. Exportiere neu, wenn du Ausrüstung oder Talente änderst.",
            ["Your other talents count where the game's own numbers have them (crit, costs, cooldowns, spells): %s."] = "Deine anderen Talente zählen dort, wo die Werte des Spiels sie schon enthalten (Krit, Kosten, Abklingzeiten, Zauber): %s.",
            ["Your own stat priority counts."] = "Deine eigene Stat-Prio zählt.",
            ["Your shots: missed"] = "Deine Schüsse: verfehlt",
            ["Your spec's own order again."] = "Wieder die Reihenfolge deiner Spezialisierung.",
            ["Your spec's stats, the one that counts most on top. Drag a stat up or down: your list and the Percent numbers follow at once; Default order gives back your spec's own order. Only with Percent: Sim rates your items by DPS."] = "Die Werte deiner Spezialisierung, der wichtigste oben. Zieh einen Wert nach oben oder unten: Deine Liste und die Prozentwerte folgen sofort; „Standard“ stellt die eigene Reihenfolge deiner Spezialisierung wieder her. Nur mit Prozent: Sim bewertet deine Gegenstände nach DPS.",
            ["Your spec, the armor and the sources your Best in Slot list, For you and the sims take. Click to change them."] = "Deine Spezialisierung, die Rüstung und die Quellen, die deine Best-in-Slot-Liste, Für dich und die Sims nehmen. Klicken, um sie zu ändern.",
            ["Your spells miss"] = "Deine Zauber verfehlen",
            ["Your start page: the best dungeon for your level and your next upgrades."] = "Deine Startseite: der beste Dungeon für dein Level und deine nächsten Verbesserungen.",
